import { memo, useCallback, useMemo, useState } from 'react';

const TableRow = memo(function TableRow({ row, onPick }) {
  return (
    <tr>
      <td>{row.name}</td>
      <td>
        <button onClick={() => onPick(row.id)}>Pick</button>
      </td>
    </tr>
  );
});

export default function FilteredTable({ items, query }) {
  const [selected, setSelected] = useState(null);

  // Manual memoization: every value must be wrapped, and any
  // future edit that adds a dependency silently breaks the cache.
  const filtered = useMemo(() => items.filter((i) => i.name.includes(query)), [items, query]);
  const onPick = useCallback((id) => setSelected(id), []);

  return (
    <table>
      <tbody>
        {filtered.map((row) => (
          <TableRow key={row.id} row={row} onPick={onPick} />
        ))}
      </tbody>
    </table>
  );
}

