export default function FilteredTable({ items, query }) {
  const [selected, setSelected] = useState(null);

  // No memoization scaffolding: the React Compiler derives the
  // dependency graph statically and caches these values and the
  // TableRow JSX subtree between renders automatically.
  const filtered = items.filter((i) => i.name.includes(query));
  const onPick = (id) => setSelected(id);

  return (
    <table>
      <tbody>
        {filtered.map((row) => (
          <TableRow key={row.id} row={row} onPick={onPick} />
        ))}
      </tbody>
    </table>
  );
}
